用 out_valid 同时表示唯一槽位是否被占用。只有槽位为空或旧输出本沿将被消费时，才能更新该槽位。

```systemverilog
module elastic_buffer8 (
  input  logic       clk,
  input  logic       rst_n,  // Synchronous active-low reset
  input  logic       in_valid,
  output logic       in_ready,
  input  logic [7:0] in_data,
  output logic       out_valid,
  input  logic       out_ready,
  output logic [7:0] out_data
);
  // Empty storage can fill even if the consumer is stalled.
  // A full slot can be replaced on the SAME edge that consumes its old word.
  assign in_ready = rst_n && (!out_valid || out_ready);

  always_ff @(posedge clk) begin
    if (!rst_n) begin
      out_valid <= 1'b0;
      out_data  <= 8'd0;
    end else if (in_ready) begin
      out_valid <= in_valid;
      if (in_valid) begin
        out_data <= in_data;
      end
      // If only the old output was consumed, clear valid and keep stale data.
    end
    // Full + !out_ready: hold BOTH payload and valid until accepted.
  end
endmodule
```

用两位 next_start 记住下一次从谁开始找；组合优先链按循环距离选择，请求为空和未实际 accept 都不消耗轮次。

```systemverilog
module round_robin4 (
  input  logic       clk,
  input  logic       rst_n,   // Synchronous active-low reset
  input  logic [3:0] req,
  input  logic       accept,  // Candidate is consumed on this edge
  output logic [3:0] grant,
  output logic       valid
);
  logic [1:0] next_start;
  logic [1:0] selected;
  logic       found;
  integer     offset, index;

  always_comb begin
    grant    = 4'b0000;
    selected = 2'd0;
    found    = 1'b0;
    // Search cyclically, starting just after the last accepted winner.
    for (offset = 0; offset < 4; offset = offset + 1) begin
      index = (int'(next_start) + offset) % 4;
      if (!found && req[index]) begin
        grant[index] = 1'b1;
        selected = index[1:0];
        found = 1'b1;
      end
    end
    valid = found;
  end

  always_ff @(posedge clk) begin
    if (!rst_n) begin
      next_start <= 2'd0;
    end else if (accept && valid) begin
      next_start <= selected + 2'd1; // Two bits wrap 3 -> 0
    end
    // Stalls and empty requests consume no service turn.
  end
endmodule
```

```systemverilog
module saturating_credit4 (
    input  logic       clk,
    input  logic       rst,
    input  logic       inc,
    input  logic       dec,
    output logic [3:0] credit
);
    // Synchronous active-high reset has priority over both requests.
    always_ff @(posedge clk) begin
        if (rst)
            credit <= 4'd0;
        else begin
            case ({inc, dec})
                2'b10: if (credit != 4'd15) credit <= credit + 4'd1;
                2'b01: if (credit != 4'd0)  credit <= credit - 4'd1;
                default: ; // Neither request, or both: keep the stored value.
            endcase
        end
    end
endmodule
