case对请求组合互斥处理；边界检查只影响单向请求，11保持。同步rst在下个上升沿优先清零。

```systemverilog
module seq1101_valid (
  input logic clk, rst, in_valid, din,
  output logic match
);
  typedef enum logic [1:0] {NONE, P1, P11, P110} state_t;
  state_t state, next_state;
  logic hit;
  // State is the longest suffix of accepted bits that is a pattern prefix.
  always_comb begin
    next_state = state;
    hit = 1'b0;
    case (state)
      NONE: if (din) next_state = P1; else next_state = NONE;
      P1: if (din) next_state = P11; else next_state = NONE;
      P11: if (din) next_state = P11; else next_state = P110;
      P110: begin
        if (din) next_state = P1; else next_state = NONE;
        hit = din;
      end
      default: next_state = NONE;
    endcase
  end
  always_ff @(posedge clk) begin
    if (rst) begin
      state <= NONE;
      match <= 1'b0;
    end else begin
      // Invalid cycles do not consume bits, but the event output clears.
      match <= 1'b0;
      if (in_valid) begin
        state <= next_state;
        match <= hit;
      end
    end
  end
endmodule
```

NONE/P1/P11/P110分别记住最长前缀。命中后退到P1保留重叠；空泡只清事件，不清前缀。

```systemverilog
module divide3_half (
  input logic clk, rst_n,
  output logic clk_div3
);
  logic [1:0] count;
  logic pos_window, neg_window;
  // A one-input-period high window repeats every three rising edges.
  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      count <= 2'd0;
      pos_window <= 1'b0;
    end else begin
      count <= (count == 2'd2) ? 2'd0 : count + 2'd1;
      pos_window <= (count == 2'd0);
    end
  end
  // Extending the high window by half an input period makes 50% duty.
  always_ff @(negedge clk or negedge rst_n) begin
    if (!rst_n) neg_window <= 1'b0;
    else neg_window <= pos_window;
  end
  assign clk_div3 = pos_window | neg_window;
endmodule
```

pos_window宽T，neg_window延后T/2，OR后宽1.5T；周期3T。异步复位清两路窗口，复位截断不在稳态脉宽承诺内。

```systemverilog
module stream_second8 (
  input logic clk, rst, start, in_valid,
  input logic [7:0] din,
  output logic second_valid,
  output logic [7:0] second_value, second_count
);
  logic have_min;
  logic [7:0] min_value, min_count;
  always_ff @(posedge clk) begin
    if (rst || start) begin
      have_min <= 1'b0;
      second_valid <= 1'b0;
      min_value <= 8'd0;
      min_count <= 8'd0;
      second_value <= 8'd0;
      second_count <= 8'd0;
    end else if (in_valid) begin
      if (!have_min) begin
        have_min <= 1'b1;
        min_value <= din;
        min_count <= 8'd1;
      end else if (din < min_value) begin
        // The former minimum becomes the second DISTINCT value.
        second_valid <= 1'b1;
        second_value <= min_value;
        second_count <= min_count;
        min_value <= din;
        min_count <= 8'd1;
      end else if (din == min_value) begin
        min_count <= min_count + 8'd1;
      end else if (!second_valid || din < second_value) begin
        second_valid <= 1'b1;
        second_value <= din;
        second_count <= 8'd1;
      end else if (din == second_value) begin
        second_count <= second_count + 8'd1;
      end
    end
  end
endmodule
```

显式标志处理未初始化；新最小把旧min_value/min_count一起转到次小，重复最小不改变第二不同值。

```systemverilog
module debounce3 (
  input logic clk, rst, sample,
  output logic stable, changed
);
  logic [1:0] run;
  // sample is already synchronous; this module is NOT a CDC synchronizer.
  always_ff @(posedge clk) begin
    if (rst) begin
      stable <= 1'b0;
      changed <= 1'b0;
      run <= 2'd0;
    end else begin
      changed <= 1'b0;
      if (sample == stable) run <= 2'd0;
      else if (run == 2'd2) begin
        stable <= sample;
        changed <= 1'b1;
        run <= 2'd0;
      end else run <= run + 2'd1;
    end
  end
endmodule
```

相同stable样本清run，第三个连续反向样本确认新stable。changed逐拍清零，只在确认时置1。

```systemverilog
module debounce_cfg #(
  parameter integer CYCLES_PER_MS = 50000
) (
  input logic clk, rst, sample,
  input logic [1:0] cfg,
  output logic stable, changed
);
  // Contract: 1 <= CYCLES_PER_MS <= 50000; inputs are already synchronous.
  localparam integer BITS = $clog2(20 * CYCLES_PER_MS + 1);
  logic [BITS-1:0] run_count, threshold;
  logic [1:0] cfg_seen;
  always_comb begin
    case (cfg)
      2'b00: threshold = 5 * CYCLES_PER_MS;
      2'b01: threshold = 10 * CYCLES_PER_MS;
      2'b10: threshold = 15 * CYCLES_PER_MS;
      default: threshold = 20 * CYCLES_PER_MS;
    endcase
  end
  always_ff @(posedge clk) begin
    if (rst) begin
      stable <= 1'b0;
      changed <= 1'b0;
      run_count <= '0;
      cfg_seen <= cfg;
    end else begin
      changed <= 1'b0;
      if (cfg != cfg_seen) begin
        // A configuration change discards both the partial run and this sample.
        cfg_seen <= cfg;
        run_count <= '0;
      end else if (sample == stable) begin
        run_count <= '0;
      end else if (run_count == threshold - 1'b1) begin
        // Old count N-1 plus this opposite sample is exactly N samples.
        stable <= sample;
        changed <= 1'b1;
        run_count <= '0;
      end else begin
        run_count <= run_count + 1'b1;
      end
    end
  end
endmodule
```

threshold由cfg给出5/10/15/20毫秒的样本数；run_count表示当前样本之前的连续反向数量。配置变化优先于输入判定，记录新值并丢弃当前样本。终点比较旧计数threshold−1，更新后清计数；changed每拍先默认清0，稳定输入不会重复触发。参数范围保证乘法不溢出且位宽非零。

```systemverilog
module sample_edges (
  input logic clk, rst, sample_valid, sample,
  output logic rise, fall, any_edge
);
  logic have_history, previous;
  always_ff @(posedge clk) begin
    if (rst) begin
      have_history <= 1'b0;
      previous <= 1'b0;
      rise <= 1'b0;
      fall <= 1'b0;
      any_edge <= 1'b0;
    end else begin
      // Invalid cycles clear events but do not consume a sample.
      rise <= 1'b0;
      fall <= 1'b0;
      any_edge <= 1'b0;
      if (sample_valid) begin
        if (have_history) begin
          rise <= !previous && sample;
          fall <= previous && !sample;
          any_edge <= previous ^ sample;
        end
        // The first valid sample establishes a baseline, not an event.
        previous <= sample;
        have_history <= 1'b1;
      end
    end
  end
endmodule
```

have_history防止启动假边沿；previous只随有效样本更新。每拍先清三个输出，有历史且本拍有效时才根据旧previous计算事件。首个有效样本无条件建立基线；rst优先使此前样本失效。三个输出都是同沿NBA后的注册结果，空泡期间为0。

```systemverilog
module even_divider #(
  parameter integer DIVIDE = 10
) (
  input logic clk, rst, en,
  output logic divided, tick
);
  // Contract: even DIVIDE, 2 <= DIVIDE <= 1024.
  localparam integer HALF = DIVIDE / 2;
  localparam integer BITS = (HALF <= 1) ? 1 : $clog2(HALF);
  logic [BITS-1:0] half_count;
  always_ff @(posedge clk) begin
    if (rst) begin
      half_count <= '0;
      divided <= 1'b0;
      tick <= 1'b0;
    end else begin
      // A stopped divider holds its phase; events never extend over a stall.
      tick <= 1'b0;
      if (en) begin
        if (half_count == HALF - 1) begin
          half_count <= '0;
          divided <= !divided;
          // The falling transition completes one full DIVIDE-edge period.
          tick <= divided;
        end else begin
          half_count <= half_count + 1'b1;
        end
      end
    end
  end
endmodule
```

half_count保存本半周期已经接受的沿数；比较HALF−1后翻转并清零。tick使用旧divided，在翻落沿完成一个完整DIVIDE计数周期。无效周期保持内部相位与输出波形，只清事件；同步复位仍需输入时钟有效沿生效。

